UPDATE lessons SET title='Year 4, Week 25, Lesson 1: Volume and cubic units', data=json_patch(data,'{"child_mission":"Volume measures how much space a solid occupies, counted in cubic units (unit cubes packed with no gaps).","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nHow many unit cubes fill a 4-by-2-by-1 rectangular box (one layer)?\n\nFEEDBACK\n8 cubic units.\n\nWATCH FOR\nCounting only the cubes you can see on the outside undercounts hidden interior cubes.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nBuild or draw twelve rectangular packs of cubes. Record length, width, height in cubes and volume for each.\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"Volume measures how much space a solid occupies, counted in cubic units (unit cubes packed with no gaps).","lesson_number":1,"lesson_role":"Concept","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA2-NSM-01"],"parent_notes":"Parent: Marking guidance for the independent task: Build or draw twelve rectangular packs of cubes. Record length, width, height in cubes and volume for each. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new numbers solved with visible working for volume; key places/values named. Do not award marks for retyping the model.\n\nParent: Written mod